#!/usr/bin/env bash\nset -e\n\n# Build the Docker image\n# Mock rationale: offline test uses local Docker, deterministic.\n docker build -t nightly-quote-mixer-test . > /dev/null\n\n# Run container in background\ncontainer_id=$(docker run -d -p 8081:8080 nightly-quote-mixer-test)\n\n# Give it a moment to start\nsleep 2\n\n# Query the service\nresponse=$(curl -s http://localhost:8081/quote)\n\n# Simple validation: response should contain the key "quote"\nif [[ "$response" == *\"quote\"* ]]; then\n  echo "Test passed"\n  exit 0\nelse\n  echo "Test failed"\n  exit 1\nfi\n\n# Cleanup\ndocker rm -f "$container_id"
